import pytest
from solution import calculate_order_total


class TestNoFee:
    """Behavior when fee_rate is zero or not provided."""

    def test_default_fee_rate_is_zero(self):
        assert calculate_order_total(10.0, 5.0) == 50.0

    def test_explicit_zero_fee_rate(self):
        assert calculate_order_total(10.0, 5.0, 0.0) == 50.0

    def test_zero_price(self):
        assert calculate_order_total(0.0, 5.0, 0.1) == 0.0

    def test_zero_amount(self):
        assert calculate_order_total(10.0, 0.0, 0.1) == 0.0

    def test_zero_price_and_amount(self):
        assert calculate_order_total(0.0, 0.0) == 0.0


class TestPositiveAmountWithFee:
    """Buying (amount > 0): fee should increase the total."""

    def test_simple_positive_case(self):
        # base_total = 100, fee = 100 * 0.1 = 10 -> total = 110
        assert calculate_order_total(10.0, 10.0, 0.1) == pytest.approx(110.0)

    def test_positive_price_and_amount_with_small_fee(self):
        assert calculate_order_total(2.5, 4.0, 0.05) == pytest.approx(10.5)

    def test_full_fee_rate(self):
        # fee_rate = 1.0 doubles the fee contribution
        assert calculate_order_total(10.0, 2.0, 1.0) == pytest.approx(40.0)

    def test_fee_increases_total_for_positive_amount(self):
        no_fee = calculate_order_total(10.0, 5.0, 0.0)
        with_fee = calculate_order_total(10.0, 5.0, 0.2)
        assert with_fee > no_fee


class TestNegativeAmountWithFee:
    """Selling (amount < 0): fee should make the total more negative."""

    def test_simple_negative_amount_case(self):
        # base_total = 10 * -10 = -100, fee = abs(-100) * 0.1 = 10
        # amount is not > 0, so fee is subtracted -> -100 - 10 = -110
        assert calculate_order_total(10.0, -10.0, 0.1) == pytest.approx(-110.0)

    def test_negative_amount_positive_price(self):
        assert calculate_order_total(5.0, -4.0, 0.1) == pytest.approx(-22.0)

    def test_fee_decreases_total_for_negative_amount(self):
        no_fee = calculate_order_total(10.0, -5.0, 0.0)
        with_fee = calculate_order_total(10.0, -5.0, 0.2)
        assert with_fee < no_fee


class TestNegativePrice:
    """Negative price flips the sign of base_total regardless of amount sign."""

    def test_negative_price_positive_amount(self):
        # base_total = -10 * 5 = -50, amount > 0 so fee is added
        # fee = abs(-50) * 0.1 = 5 -> total = -50 + 5 = -45
        assert calculate_order_total(-10.0, 5.0, 0.1) == pytest.approx(-45.0)

    def test_negative_price_negative_amount(self):
        # base_total = -10 * -5 = 50, amount not > 0 so fee is subtracted
        # fee = abs(50) * 0.1 = 5 -> total = 50 - 5 = 45
        assert calculate_order_total(-10.0, -5.0, 0.1) == pytest.approx(45.0)


class TestBoundaryAmount:
    """amount == 0 is not > 0, so the fee branch subtracts (but fee is 0 anyway)."""

    def test_amount_exactly_zero_with_fee_rate(self):
        assert calculate_order_total(100.0, 0.0, 0.5) == 0.0

    def test_amount_exactly_zero_negative_price(self):
        assert calculate_order_total(-50.0, 0.0, 0.3) == 0.0


class TestFloatPrecision:
    def test_fractional_values(self):
        result = calculate_order_total(3.3333, 3.0, 0.015)
        base_total = 3.3333 * 3.0
        expected = base_total + abs(base_total) * 0.015
        assert result == pytest.approx(expected)

    def test_large_numbers(self):
        result = calculate_order_total(1_000_000.0, 1_000.0, 0.01)
        assert result == pytest.approx(1_000_000_000.0 + 10_000_000.0)

    def test_small_fee_rate_precision(self):
        result = calculate_order_total(19.99, 3.0, 0.0001)
        base_total = 19.99 * 3.0
        expected = base_total + abs(base_total) * 0.0001
        assert result == pytest.approx(expected)


class TestReturnType:
    def test_returns_float(self):
        result = calculate_order_total(10, 5, 0.1)
        assert isinstance(result, float)

    def test_returns_float_with_integer_inputs_and_no_fee(self):
        result = calculate_order_total(10, 5)
        assert isinstance(result, float)
        assert result == 50.0
