import pytest

from solution import count_orders_by_type


class Order:
    """Simple stand-in for an order object with an order_type attribute."""

    def __init__(self, order_type):
        self.order_type = order_type


def test_empty_list_returns_empty_dict():
    assert count_orders_by_type([]) == {}


def test_single_order():
    orders = [Order("food")]
    assert count_orders_by_type(orders) == {"food": 1}


def test_multiple_orders_same_type():
    orders = [Order("food"), Order("food"), Order("food")]
    assert count_orders_by_type(orders) == {"food": 3}


def test_multiple_orders_different_types():
    orders = [
        Order("food"),
        Order("drink"),
        Order("food"),
        Order("dessert"),
        Order("drink"),
        Order("food"),
    ]
    assert count_orders_by_type(orders) == {"food": 3, "drink": 2, "dessert": 1}


def test_returns_dict_instance():
    orders = [Order("food")]
    result = count_orders_by_type(orders)
    assert isinstance(result, dict)


def test_does_not_mutate_input_list():
    orders = [Order("food"), Order("drink")]
    orders_copy = list(orders)
    count_orders_by_type(orders)
    assert orders == orders_copy


def test_order_types_are_case_sensitive():
    orders = [Order("food"), Order("Food"), Order("FOOD")]
    result = count_orders_by_type(orders)
    assert result == {"food": 1, "Food": 1, "FOOD": 1}


def test_numeric_order_type_keys():
    orders = [Order(1), Order(2), Order(1), Order(3), Order(2), Order(1)]
    assert count_orders_by_type(orders) == {1: 3, 2: 2, 3: 1}


def test_none_order_type_is_counted():
    orders = [Order(None), Order("food"), Order(None)]
    assert count_orders_by_type(orders) == {None: 2, "food": 1}


def test_boolean_order_type_keys():
    orders = [Order(True), Order(False), Order(True)]
    result = count_orders_by_type(orders)
    assert result == {True: 2, False: 1}


def test_large_number_of_orders():
    orders = [Order("type_a") for _ in range(1000)] + [Order("type_b") for _ in range(500)]
    result = count_orders_by_type(orders)
    assert result == {"type_a": 1000, "type_b": 500}


def test_single_order_repeated_type_string_values_preserved():
    orders = [Order("express"), Order("standard"), Order("express")]
    result = count_orders_by_type(orders)
    assert result["express"] == 2
    assert result["standard"] == 1
    assert set(result.keys()) == {"express", "standard"}


def test_missing_order_type_attribute_raises_attribute_error():
    class BadOrder:
        pass

    with pytest.raises(AttributeError):
        count_orders_by_type([BadOrder()])


def test_input_can_be_any_iterable_not_just_list():
    def order_generator():
        yield Order("food")
        yield Order("drink")
        yield Order("food")

    result = count_orders_by_type(order_generator())
    assert result == {"food": 2, "drink": 1}
