import pytest
from solution import calculate_order_total


class TestBasicNoFee:
    def test_positive_amount_no_fee(self):
        assert calculate_order_total(10.0, 5.0) == 50.0

    def test_negative_amount_no_fee(self):
        assert calculate_order_total(10.0, -5.0) == -50.0

    def test_zero_amount_no_fee(self):
        assert calculate_order_total(10.0, 0.0) == 0.0

    def test_zero_price_no_fee(self):
        assert calculate_order_total(0.0, 5.0) == 0.0

    def test_default_fee_rate_is_zero(self):
        assert calculate_order_total(20.0, 3.0) == pytest.approx(60.0)


class TestBuyOrdersWithFee:
    def test_positive_amount_adds_fee(self):
        # base_total = 100, fee = 100 * 0.1 = 10, total = 110
        result = calculate_order_total(20.0, 5.0, 0.1)
        assert result == pytest.approx(110.0)

    def test_small_fee_rate(self):
        result = calculate_order_total(100.0, 2.0, 0.01)
        assert result == pytest.approx(202.0)

    def test_full_fee_rate_one(self):
        # fee_rate of 1.0 doubles the base total for buys
        result = calculate_order_total(10.0, 10.0, 1.0)
        assert result == pytest.approx(200.0)


class TestSellOrdersWithFee:
    def test_negative_amount_subtracts_fee(self):
        # base_total = -100, fee = abs(-100) * 0.1 = 10, total = -110
        result = calculate_order_total(20.0, -5.0, 0.1)
        assert result == pytest.approx(-110.0)

    def test_small_fee_rate_negative_amount(self):
        result = calculate_order_total(100.0, -2.0, 0.01)
        assert result == pytest.approx(-202.0)

    def test_full_fee_rate_one_negative(self):
        result = calculate_order_total(10.0, -10.0, 1.0)
        assert result == pytest.approx(-200.0)


class TestZeroAmountWithFee:
    def test_zero_amount_no_fee_effect(self):
        # amount == 0 means amount > 0 is False, so fee is subtracted,
        # but base_total and fee are both 0 anyway
        result = calculate_order_total(50.0, 0.0, 0.2)
        assert result == 0.0


class TestNegativePrice:
    def test_negative_price_positive_amount(self):
        # base_total = -50, amount > 0 so fee is added
        # fee = abs(-50) * 0.1 = 5, total = -50 + 5 = -45
        result = calculate_order_total(-10.0, 5.0, 0.1)
        assert result == pytest.approx(-45.0)

    def test_negative_price_negative_amount(self):
        # base_total = 50 (neg * neg), amount < 0 so fee is subtracted
        # fee = abs(50) * 0.1 = 5, total = 50 - 5 = 45
        result = calculate_order_total(-10.0, -5.0, 0.1)
        assert result == pytest.approx(45.0)

    def test_negative_price_no_fee(self):
        result = calculate_order_total(-10.0, 5.0)
        assert result == pytest.approx(-50.0)


class TestFractionalValues:
    def test_fractional_price_and_amount(self):
        result = calculate_order_total(3.5, 2.25, 0.05)
        base_total = 3.5 * 2.25
        expected = base_total + abs(base_total) * 0.05
        assert result == pytest.approx(expected)

    def test_fractional_negative_amount(self):
        result = calculate_order_total(3.5, -2.25, 0.05)
        base_total = 3.5 * -2.25
        expected = base_total - abs(base_total) * 0.05
        assert result == pytest.approx(expected)


class TestKeywordArguments:
    def test_call_with_keyword_args(self):
        result = calculate_order_total(price=10.0, amount=5.0, fee_rate=0.1)
        assert result == pytest.approx(55.0)

    def test_call_with_fee_rate_omitted_as_keyword(self):
        result = calculate_order_total(price=10.0, amount=-5.0)
        assert result == pytest.approx(-50.0)


class TestLargeAndSmallNumbers:
    def test_large_values(self):
        result = calculate_order_total(1_000_000.0, 1_000.0, 0.001)
        base_total = 1_000_000.0 * 1_000.0
        expected = base_total + abs(base_total) * 0.001
        assert result == pytest.approx(expected)

