        result = calculate_order_total(20.0, 5.0, 0.1)
        assert result == pytest.approx(110.0)

    def test_small_fee_rate(self):
        result = calculate_order_total(100.0, 2.0, 0.01)
        assert result == pytest.approx(202.0)

    def test_full_fee_rate_one(self):
        # fee_rate of 1.0 doubles the base total for buys
        result = calculate_order_total(10.0, 10.0, 1.0)
        assert result == pytest.approx(200.0)


class TestSellOrdersWithFee:
    def test_negative_amount_subtracts_fee(self):
        # base_total = -100, fee = abs(-100) * 0.1 = 10, total = -110
        result = calculate_order_total(20.0, -5.0, 0.1)
        assert result == pytest.approx(-110.0)

    def test_small_fee_rate_negative_amount(self):
        result = calculate_order_total(100.0, -2.0, 0.01)
        assert result == pytest.approx(-202.0)

