import pytest
from types import SimpleNamespace

from solution import count_orders_by_type


def make_order(order_type):
    """Helper to build a minimal object with an order_type attribute."""
    return SimpleNamespace(order_type=order_type)


class TestCountOrdersByType:
    def test_empty_list_returns_empty_dict(self):
        result = count_orders_by_type([])
        assert result == {}

    def test_single_order(self):
        orders = [make_order("buy")]
        result = count_orders_by_type(orders)
        assert result == {"buy": 1}

    def test_multiple_orders_same_type(self):
        orders = [make_order("buy"), make_order("buy"), make_order("buy")]
        result = count_orders_by_type(orders)
        assert result == {"buy": 3}

    def test_multiple_orders_different_types(self):
        orders = [
            make_order("buy"),
            make_order("sell"),
            make_order("buy"),
            make_order("cancel"),
            make_order("sell"),
            make_order("buy"),
        ]
        result = count_orders_by_type(orders)
        assert result == {"buy": 3, "sell": 2, "cancel": 1}

    def test_order_of_input_does_not_affect_counts(self):
        orders_a = [make_order("x"), make_order("y"), make_order("x")]
        orders_b = [make_order("y"), make_order("x"), make_order("x")]
        assert count_orders_by_type(orders_a) == count_orders_by_type(orders_b)

    def test_returns_dict_type(self):
        orders = [make_order("buy")]
        result = count_orders_by_type(orders)
        assert isinstance(result, dict)

    def test_non_string_order_type_keys(self):
        # order_type can be any hashable value, e.g. an int or enum-like object
        orders = [make_order(1), make_order(2), make_order(1)]
        result = count_orders_by_type(orders)
        assert result == {1: 2, 2: 1}

    def test_large_number_of_orders(self):
        orders = [make_order("a") for _ in range(500)] + [make_order("b") for _ in range(250)]
        result = count_orders_by_type(orders)
        assert result == {"a": 500, "b": 250}
        assert sum(result.values()) == len(orders)

    def test_single_order_type_repeated_many_times(self):
        orders = [make_order("only") for _ in range(10)]
        result = count_orders_by_type(orders)
        assert result == {"only": 10}

    def test_missing_order_type_attribute_raises_attribute_error(self):
        class NoTypeOrder:
            pass

        with pytest.raises(AttributeError):
            count_orders_by_type([NoTypeOrder()])

    def test_does_not_mutate_input_list(self):
        orders = [make_order("buy"), make_order("sell")]
        orders_copy = list(orders)
        count_orders_by_type(orders)
        assert orders == orders_copy

    def test_all_distinct_types_each_counted_once(self):
        types = ["a", "b", "c", "d", "e"]
        orders = [make_order(t) for t in types]
        result = count_orders_by_type(orders)
        assert result == {t: 1 for t in types}
