from types import SimpleNamespace

from solution import count_orders_by_type


def make_order(order_type):
    """Helper to build a minimal object with an order_type attribute."""
    return SimpleNamespace(order_type=order_type)


class TestCountOrdersByType:
    def test_empty_list_returns_empty_dict(self):
        result = count_orders_by_type([])
        assert result == {}

    def test_single_order(self):
        orders = [make_order("buy")]
        result = count_orders_by_type(orders)
        assert result == {"buy": 1}

    def test_multiple_orders_same_type(self):
        orders = [make_order("buy"), make_order("buy"), make_order("buy")]
        result = count_orders_by_type(orders)
        assert result == {"buy": 3}

    def test_multiple_orders_different_types(self):
        orders = [
            make_order("buy"),
            make_order("sell"),
            make_order("buy"),
            make_order("cancel"),
            make_order("sell"),
            make_order("buy"),
        ]
        result = count_orders_by_type(orders)
        assert result == {"buy": 3, "sell": 2, "cancel": 1}

    def test_order_of_input_does_not_affect_counts(self):
        orders_a = [make_order("x"), make_order("y"), make_order("x")]
        orders_b = [make_order("y"), make_order("x"), make_order("x")]
        assert count_orders_by_type(orders_a) == count_orders_by_type(orders_b)

    def test_returns_dict_type(self):
