import pytest

from solution import _process_websocket_test_results


class TestProcessWebsocketTestResults:
    def test_error_present_returns_false(self, capsys):
        result_container = {"error": "connection refused", "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: connection refused" in captured.out

    def test_error_present_overrides_success_true(self, capsys):
        result_container = {"error": "timeout", "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: timeout" in captured.out

    def test_success_true_no_error_returns_true(self, capsys):
        result_container = {"error": None, "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""

    def test_success_true_with_empty_string_error_returns_true(self, capsys):
        result_container = {"error": "", "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""

    def test_no_error_no_success_returns_false_unknown_error(self, capsys):
        result_container = {"error": None, "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out

    def test_no_error_falsy_success_falsy_variants(self, capsys):
        result_container = {"error": "", "success": 0}

        result = _process_websocket_test_results(result_container)

        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out

    def test_error_falsy_value_zero_and_success_true(self):
        result_container = {"error": 0, "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is True

    def test_error_message_included_in_output(self, capsys):
        result_container = {"error": "handshake failed", "success": False}

        _process_websocket_test_results(result_container)

        captured = capsys.readouterr()
        assert "handshake failed" in captured.out

    def test_missing_error_key_raises_keyerror(self):
        result_container = {"success": True}

        with pytest.raises(KeyError):
            _process_websocket_test_results(result_container)

    def test_missing_success_key_raises_keyerror_when_error_falsy(self):
        result_container = {"error": None}

        with pytest.raises(KeyError):
            _process_websocket_test_results(result_container)

    def test_missing_success_key_not_needed_when_error_truthy(self):
        result_container = {"error": "boom"}

        result = _process_websocket_test_results(result_container)

        assert result is False

    def test_return_type_is_bool_on_success(self):
        result_container = {"error": None, "success": True}

        result = _process_websocket_test_results(result_container)

        assert isinstance(result, bool)

    def test_return_type_is_bool_on_error(self):
        result_container = {"error": "oops", "success": False}

        result = _process_websocket_test_results(result_container)

        assert isinstance(result, bool)

    def test_return_type_is_bool_on_unknown_error(self):
        result_container = {"error": None, "success": None}

        result = _process_websocket_test_results(result_container)

        assert isinstance(result, bool)
