import builtins
from unittest.mock import MagicMock

import pytest

from solution import _process_websocket_test_results


class TestProcessWebsocketTestResults:
    def test_returns_false_and_prints_error_message_when_error_present(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": "connection refused", "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with(
            "❌ WebSocket test failed: connection refused"
        )

    def test_error_branch_takes_priority_over_success(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": "timeout", "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with("❌ WebSocket test failed: timeout")

    def test_returns_true_when_no_error_and_success_true(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": None, "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is True
        mock_print.assert_not_called()

    def test_returns_true_with_falsy_empty_string_error_and_success_true(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": "", "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is True
        mock_print.assert_not_called()

    def test_returns_false_and_prints_unknown_error_when_no_error_and_no_success(
        self, monkeypatch
    ):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": None, "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with("❌ WebSocket test failed: Unknown error")

    def test_returns_false_and_prints_unknown_error_when_both_falsy_empty_string_and_false(
        self, monkeypatch
    ):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": "", "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with("❌ WebSocket test failed: Unknown error")

    def test_returns_false_and_prints_unknown_error_when_both_falsy_none_and_none(
        self, monkeypatch
    ):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": None, "success": None}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with("❌ WebSocket test failed: Unknown error")

    def test_truthy_non_string_error_is_formatted_via_fstring(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        error_obj = {"code": 500, "message": "server error"}
        result_container = {"error": error_obj, "success": False}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with(f"❌ WebSocket test failed: {error_obj}")

    def test_missing_error_key_raises_key_error(self):
        result_container = {"success": True}

        with pytest.raises(KeyError):
            _process_websocket_test_results(result_container)

    def test_missing_success_key_raises_key_error_when_error_is_falsy(self):
        result_container = {"error": None}

        with pytest.raises(KeyError):
            _process_websocket_test_results(result_container)

    def test_does_not_raise_missing_success_key_when_error_is_truthy(self, monkeypatch):
        mock_print = MagicMock()
        monkeypatch.setattr(builtins, "print", mock_print)

        result_container = {"error": "boom"}

        result = _process_websocket_test_results(result_container)

        assert result is False
        mock_print.assert_called_once_with("❌ WebSocket test failed: boom")
