class TestCountOrdersByType:
    def test_empty_list_returns_empty_dict(self):
        result = count_orders_by_type([])
        assert result == {}

    def test_single_order_returns_count_one(self):
        orders = make_orders("buy")
        result = count_orders_by_type(orders)
        assert result == {"buy": 1}

    def test_multiple_orders_same_type(self):
        orders = make_orders("buy", "buy", "buy")
        result = count_orders_by_type(orders)
        assert result == {"buy": 3}

    def test_multiple_orders_different_types(self):
        orders = make_orders("buy", "sell", "buy", "hold", "sell", "sell")
        result = count_orders_by_type(orders)
        assert result == {"buy": 2, "sell": 3, "hold": 1}

    def test_preserves_all_distinct_types(self):
        orders = make_orders("a", "b", "c", "d")
        result = count_orders_by_type(orders)
        assert result == {"a": 1, "b": 1, "c": 1, "d": 1}

    def test_order_type_attribute_accessed_not_other_attributes(self):
        # Ensure the function only relies on `order_type`, not any other
        # attribute or method of the order object (isolation from collaborator internals).
        class MinimalOrder:
            def __init__(self, order_type):
                self.order_type = order_type

            def __getattr__(self, name):
                if name == "order_type":
                    raise AttributeError(name)
                raise AssertionError(f"Unexpected attribute access: {name}")

        orders = [MinimalOrder("buy"), MinimalOrder("sell")]
        result = count_orders_by_type(orders)
        assert result == {"buy": 1, "sell": 1}

    def test_does_not_mutate_input_list(self):
        orders = make_orders("buy", "sell")
        orders_copy = list(orders)
        count_orders_by_type(orders)
        assert orders == orders_copy

    def test_returns_new_dict_each_call(self):
        orders = make_orders("buy")
        result1 = count_orders_by_type(orders)
        result2 = count_orders_by_type(orders)
        assert result1 == result2
        assert result1 is not result2

    def test_order_type_can_be_non_string_hashable(self):
        # order_type could be an enum or int in some systems; ensure no
        # assumption is made that it's specifically a str.
        orders = make_orders(1, 2, 1, 3, 2, 1)
        result = count_orders_by_type(orders)
        assert result == {1: 3, 2: 2, 3: 1}

    def test_order_type_none_is_valid_key(self):
        orders = make_orders(None, None, "buy")
        result = count_orders_by_type(orders)
        assert result == {None: 2, "buy": 1}

    def test_large_number_of_orders(self):
        orders = make_orders(*(["buy"] * 500 + ["sell"] * 250))
        result = count_orders_by_type(orders)
        assert result == {"buy": 500, "sell": 250}

    def test_missing_order_type_attribute_raises_attribute_error(self):
        class NoTypeOrder:
            pass

        with pytest.raises(AttributeError):
            count_orders_by_type([NoTypeOrder()])

    def test_input_is_generator_not_just_list(self):
        # The function type-hints `list`, but its implementation only relies
        # on iteration, so verify it works with any iterable of order-like objects.
        orders_gen = (FakeOrder(t) for t in ["buy", "sell", "buy"])
        result = count_orders_by_type(orders_gen)
        assert result == {"buy": 2, "sell": 1}
