import math

import pytest

from solution import safe_float_convert


class TestValidConversions:
    """Cases where value is directly convertible to float without needing the default."""

    def test_positive_int(self):
        assert safe_float_convert(5) == 5.0

    def test_negative_int(self):
        assert safe_float_convert(-5) == -5.0

    def test_zero_int(self):
        assert safe_float_convert(0) == 0.0

    def test_positive_float(self):
        assert safe_float_convert(3.14) == 3.14

    def test_negative_float(self):
        assert safe_float_convert(-3.14) == -3.14

    def test_float_passthrough_identity(self):
        assert safe_float_convert(2.5) == 2.5

    def test_numeric_string_int(self):
        assert safe_float_convert("42") == 42.0

    def test_numeric_string_float(self):
        assert safe_float_convert("3.14") == 3.14

    def test_numeric_string_negative(self):
        assert safe_float_convert("-7.5") == -7.5

    def test_numeric_string_with_leading_trailing_whitespace(self):
        assert safe_float_convert("  10.5  ") == 10.5

    def test_numeric_string_with_plus_sign(self):
        assert safe_float_convert("+5.5") == 5.5

    def test_numeric_string_scientific_notation(self):
        assert safe_float_convert("1e3") == 1000.0

    def test_bool_true_converts_to_one(self):
        # bool is a subclass of int, float(True) == 1.0
        assert safe_float_convert(True) == 1.0

    def test_bool_false_converts_to_zero(self):
        assert safe_float_convert(False) == 0.0

    def test_string_infinity(self):
        assert safe_float_convert("inf") == float("inf")

    def test_string_nan_returns_nan(self):
        result = safe_float_convert("nan")
        assert math.isnan(result)

    def test_return_type_is_float_for_int_input(self):
        assert isinstance(safe_float_convert(7), float)

    def test_return_type_is_float_for_string_input(self):
        assert isinstance(safe_float_convert("7"), float)


class TestInvalidConversionsUseDefault:
    """Cases where conversion raises ValueError/TypeError and default should be returned."""

    def test_non_numeric_string_returns_default(self):
        assert safe_float_convert("abc") == 0.0

    def test_empty_string_returns_default(self):
        assert safe_float_convert("") == 0.0

    def test_none_returns_default(self):
        assert safe_float_convert(None) == 0.0

    def test_list_returns_default(self):
        assert safe_float_convert([1, 2, 3]) == 0.0

    def test_dict_returns_default(self):
        assert safe_float_convert({"a": 1}) == 0.0

    def test_object_without_float_support_returns_default(self):
        class NotConvertible:
            pass

        assert safe_float_convert(NotConvertible()) == 0.0

    def test_mixed_alphanumeric_string_returns_default(self):
        assert safe_float_convert("12abc") == 0.0

    def test_whitespace_only_string_returns_default(self):
        assert safe_float_convert("   ") == 0.0

    def test_string_with_multiple_dots_returns_default(self):
        assert safe_float_convert("1.2.3") == 0.0

    def test_string_with_internal_spaces_returns_default(self):
        assert safe_float_convert("1 2 3") == 0.0


class TestCustomDefaultValue:
    """Ensure the provided default (not just 0.0) is honored on failure."""

    def test_custom_default_used_on_invalid_string(self):
        assert safe_float_convert("not_a_number", default=99.9) == 99.9

    def test_custom_default_used_on_none(self):
        assert safe_float_convert(None, default=-1.0) == -1.0

    def test_custom_default_not_used_on_valid_input(self):
        assert safe_float_convert("3.5", default=99.9) == 3.5

    def test_custom_default_negative(self):
        assert safe_float_convert("bad", default=-42.0) == -42.0

    def test_custom_default_zero_explicit(self):
        assert safe_float_convert("bad", default=0.0) == 0.0

    def test_custom_default_nan(self):
        result = safe_float_convert("bad", default=float("nan"))
        assert math.isnan(result)

    def test_default_return_type_preserved(self):
        # default is returned as-is; if caller passes an int-like default, it is returned unchanged
        result = safe_float_convert("bad", default=5)
        assert result == 5
        assert isinstance(result, int)


class TestEdgeCasesAroundExceptionHandling:
    """Confirm only ValueError/TypeError are swallowed; behavior is otherwise as expected."""

    def test_string_hex_number_returns_default(self):
