from solution import _process_websocket_test_results


class TestErrorPresent:
    def test_error_truthy_returns_false(self, capsys):
        result = _process_websocket_test_results(
            {"error": "connection refused", "success": True}
        )
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: connection refused" in captured.out

    def test_error_takes_priority_over_success(self, capsys):
        result = _process_websocket_test_results(
            {"error": "timeout", "success": True}
        )
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: timeout" in captured.out

    def test_error_message_included_verbatim(self, capsys):
        result = _process_websocket_test_results(
            {"error": "some weird error message", "success": False}
        )
        assert result is False
        captured = capsys.readouterr()
        assert "some weird error message" in captured.out

    def test_error_truthy_non_string(self, capsys):
        result = _process_websocket_test_results(
            {"error": {"code": 500}, "success": False}
        )
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: {'code': 500}" in captured.out

    def test_error_truthy_nonzero_int(self, capsys):
        result = _process_websocket_test_results({"error": 1, "success": False})
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: 1" in captured.out


