    def test_success_true_no_error_returns_true(self, capsys):
        result = _process_websocket_test_results({"error": None, "success": True})
        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""

    def test_success_true_empty_string_error_returns_true(self, capsys):
        result = _process_websocket_test_results({"error": "", "success": True})
        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""

    def test_success_true_error_false_returns_true(self, capsys):
        result = _process_websocket_test_results({"error": False, "success": True})
        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""

    def test_success_true_error_zero_returns_true(self, capsys):
        result = _process_websocket_test_results({"error": 0, "success": True})
        assert result is True
        captured = capsys.readouterr()
        assert captured.out == ""


class TestNoErrorNoSuccess:
    def test_no_error_no_success_returns_false(self, capsys):
        result = _process_websocket_test_results({"error": None, "success": False})
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out

    def test_both_falsy_empty_string_and_false(self, capsys):
        result = _process_websocket_test_results({"error": "", "success": False})
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out

    def test_both_falsy_none_and_none(self, capsys):
        result = _process_websocket_test_results({"error": None, "success": None})
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out

    def test_error_zero_success_zero(self, capsys):
        result = _process_websocket_test_results({"error": 0, "success": 0})
        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: Unknown error" in captured.out


class TestReturnTypeIsBool:
    @pytest.mark.parametrize(
        "container",
        [
            {"error": "boom", "success": False},
            {"error": None, "success": True},
            {"error": None, "success": False},
        ],
    )
    def test_return_value_is_actual_bool_or_input_type(self, container):
        result = _process_websocket_test_results(container)
        # The implementation returns literal True/False in the error and
        # unknown-error branches, and the raw `success` value when truthy.
        if container["error"]:
            assert result is False
        elif container["success"]:
            assert result == container["success"]
        else:
            assert result is False

    def test_success_truthy_non_bool_value_returned_as_is(self):
        # When success is a truthy non-bool, the function returns True
        # via the `elif` branch evaluating truthiness, but the returned
        # literal is the Python constant True, not the original value.
        result = _process_websocket_test_results({"error": None, "success": "yes"})
        assert result is True
