import pytest

from solution import count_orders_by_type


class Order:
    """Simple stand-in for an order object with an order_type attribute."""

    def __init__(self, order_type):
        self.order_type = order_type


def test_empty_list_returns_empty_dict():
    assert count_orders_by_type([]) == {}


def test_single_order():
    orders = [Order("buy")]
    assert count_orders_by_type(orders) == {"buy": 1}


def test_multiple_orders_single_type():
    orders = [Order("buy"), Order("buy"), Order("buy")]
    assert count_orders_by_type(orders) == {"buy": 3}


def test_multiple_distinct_types():
    orders = [Order("buy"), Order("sell"), Order("buy")]
    assert count_orders_by_type(orders) == {"buy": 2, "sell": 1}


def test_multiple_types_various_counts():
    orders = [
        Order("buy"),
        Order("sell"),
        Order("buy"),
        Order("limit"),
        Order("sell"),
        Order("sell"),
    ]
    assert count_orders_by_type(orders) == {"buy": 2, "sell": 3, "limit": 1}


def test_preserves_first_seen_key_order():
    # dict preserves insertion order; verify it matches first-occurrence order of types
    orders = [Order("c"), Order("a"), Order("c"), Order("b"), Order("a")]
    result = count_orders_by_type(orders)
    assert list(result.keys()) == ["c", "a", "b"]
    assert result == {"c": 2, "a": 2, "b": 1}


def test_order_type_can_be_non_string_hashable():
    # order_type is used directly as a dict key, so any hashable value works
    orders = [Order(1), Order(2), Order(1), Order(None), Order(None), Order(None)]
    assert count_orders_by_type(orders) == {1: 2, 2: 1, None: 3}


def test_order_type_boolean_values():
    orders = [Order(True), Order(False), Order(True)]
    result = count_orders_by_type(orders)
    assert result == {True: 2, False: 1}


def test_does_not_mutate_input_list():
    orders = [Order("buy"), Order("sell")]
    original_ids = [id(o) for o in orders]
    count_orders_by_type(orders)
    assert [id(o) for o in orders] == original_ids
    assert len(orders) == 2


def test_returns_new_dict_each_call():
    orders = [Order("buy")]
    result1 = count_orders_by_type(orders)
    result2 = count_orders_by_type(orders)
    assert result1 == result2
    assert result1 is not result2


def test_missing_order_type_attribute_raises_attribute_error():
    class NoTypeOrder:
        pass

    with pytest.raises(AttributeError):
        count_orders_by_type([NoTypeOrder()])


def test_large_number_of_orders():
    orders = [Order("a") for _ in range(1000)] + [Order("b") for _ in range(500)]
    result = count_orders_by_type(orders)
    assert result == {"a": 1000, "b": 500}
