import pytest

from solution import calculate_order_total


class TestNoFee:
    """When fee_rate is 0 (or omitted), the result is just price * amount."""

    def test_default_fee_rate_positive_amount(self):
        assert calculate_order_total(10.0, 5.0) == pytest.approx(50.0)

