    def test_zero_price(self):
        assert calculate_order_total(0.0, 10.0, 0.1) == pytest.approx(0.0)

    def test_zero_price_and_amount(self):
        assert calculate_order_total(0.0, 0.0, 0.2) == pytest.approx(0.0)


class TestPositiveAmountWithFee:
    """For buys (amount > 0), the fee is added on top of the base total."""

    def test_simple_buy_with_fee(self):
        # base_total = 100 * 2 = 200, fee = 200 * 0.01 = 2
        assert calculate_order_total(100.0, 2.0, 0.01) == pytest.approx(202.0)

    def test_buy_with_full_fee_rate(self):
        # base_total = 50 * 1 = 50, fee = 50 * 1.0 = 50
        assert calculate_order_total(50.0, 1.0, 1.0) == pytest.approx(100.0)

    def test_buy_with_negative_price(self):
        # base_total = -10 * 5 = -50, fee = abs(-50) * 0.1 = 5
        # amount > 0 -> fee added: -50 + 5 = -45
        assert calculate_order_total(-10.0, 5.0, 0.1) == pytest.approx(-45.0)

    def test_buy_with_fractional_values(self):
        # base_total = 19.99 * 3 = 59.97, fee = 59.97 * 0.025 = 1.49925
        assert calculate_order_total(19.99, 3.0, 0.025) == pytest.approx(61.46925)


class TestNegativeAmountWithFee:
    """For sells (amount < 0), the fee is subtracted from the base total."""

    def test_simple_sell_with_fee(self):
        # base_total = 100 * -2 = -200, fee = abs(-200) * 0.01 = 2
        # amount > 0 is False -> fee subtracted: -200 - 2 = -202
        assert calculate_order_total(100.0, -2.0, 0.01) == pytest.approx(-202.0)

    def test_sell_with_negative_price(self):
        # base_total = -10 * -5 = 50, fee = abs(50) * 0.1 = 5
        # amount > 0 is False -> fee subtracted: 50 - 5 = 45
        assert calculate_order_total(-10.0, -5.0, 0.1) == pytest.approx(45.0)

    def test_sell_with_fractional_values(self):
        # base_total = 19.99 * -3 = -59.97, fee = 59.97 * 0.025 = 1.49925
        assert calculate_order_total(19.99, -3.0, 0.025) == pytest.approx(-61.46925)

    def test_sell_with_full_fee_rate(self):
        # base_total = 50 * -1 = -50, fee = 50 * 1.0 = 50
        # amount > 0 is False -> -50 - 50 = -100
        assert calculate_order_total(50.0, -1.0, 1.0) == pytest.approx(-100.0)


class TestParametrizedBehaviour:
    @pytest.mark.parametrize(
        "price, amount, fee_rate, expected",
        [
            (10.0, 5.0, 0.0, 50.0),
            (10.0, -5.0, 0.0, -50.0),
            (100.0, 2.0, 0.01, 202.0),
