            (0.0, 5.0, 0.5, 0.0),
            (5.0, 0.0, 0.5, 0.0),
        ],
    )
    def test_various_combinations(self, price, amount, fee_rate, expected):
        assert calculate_order_total(price, amount, fee_rate) == pytest.approx(expected)

    @pytest.mark.parametrize("fee_rate", [0.0, 0.01, 0.1, 0.5, 1.0])
    def test_fee_never_flips_sign_relationship_for_buy(self, fee_rate):
        # For a buy with positive base_total, adding a non-negative fee
        # should never decrease the result below the base total.
        price, amount = 30.0, 4.0
        base_total = price * amount
        result = calculate_order_total(price, amount, fee_rate)
        assert result >= base_total

    @pytest.mark.parametrize("fee_rate", [0.0, 0.01, 0.1, 0.5, 1.0])
    def test_fee_never_flips_sign_relationship_for_sell(self, fee_rate):
