        price, amount = 30.0, -4.0
        base_total = price * amount
        result = calculate_order_total(price, amount, fee_rate)
        assert result <= base_total


class TestReturnType:
    def test_returns_numeric_value(self):
        result = calculate_order_total(10.0, 5.0, 0.01)
        assert isinstance(result, (int, float))
