import pytest

from solution import count_orders_by_type


class Order:
    """Simple stand-in for an order object with an order_type attribute."""

    def __init__(self, order_type):
        self.order_type = order_type


def make_orders(*types):
    return [Order(t) for t in types]


def test_empty_list_returns_empty_dict():
    assert count_orders_by_type([]) == {}


def test_single_order():
    orders = make_orders("standard")
    assert count_orders_by_type(orders) == {"standard": 1}


def test_multiple_orders_single_type():
    orders = make_orders("standard", "standard", "standard")
    assert count_orders_by_type(orders) == {"standard": 3}


def test_multiple_orders_multiple_types():
    orders = make_orders("standard", "express", "standard", "priority", "express", "express")
    result = count_orders_by_type(orders)
    assert result == {"standard": 2, "express": 3, "priority": 1}


def test_two_distinct_types_equal_counts():
    orders = make_orders("online", "in_store", "online", "in_store")
    result = count_orders_by_type(orders)
    assert result == {"online": 2, "in_store": 2}


def test_order_of_orders_does_not_affect_counts():
    orders_a = make_orders("a", "b", "a", "c", "b", "a")
    orders_b = make_orders("a", "a", "a", "b", "b", "c")
    assert count_orders_by_type(orders_a) == count_orders_by_type(orders_b)


def test_returns_dict_type():
    orders = make_orders("standard")
    result = count_orders_by_type(orders)
    assert isinstance(result, dict)


def test_counts_are_integers():
    orders = make_orders("standard", "standard")
    result = count_orders_by_type(orders)
    for value in result.values():
        assert isinstance(value, int)


def test_keys_match_distinct_order_types():
    orders = make_orders("standard", "express", "standard", "gift")
    result = count_orders_by_type(orders)
    assert set(result.keys()) == {"standard", "express", "gift"}


def test_total_counts_sum_to_number_of_orders():
    orders = make_orders("standard", "express", "standard", "priority", "express", "express")
    result = count_orders_by_type(orders)
    assert sum(result.values()) == len(orders)


def test_case_sensitive_types_treated_as_distinct():
    orders = make_orders("Standard", "standard")
    result = count_orders_by_type(orders)
    assert result == {"Standard": 1, "standard": 1}


def test_numeric_order_type_values():
    orders = make_orders(1, 2, 1, 3, 1)
    result = count_orders_by_type(orders)
    assert result == {1: 3, 2: 1, 3: 1}


def test_does_not_mutate_input_list():
    orders = make_orders("standard", "express")
    orders_copy = list(orders)
    count_orders_by_type(orders)
    assert orders == orders_copy
