"""Unit tests for the count_orders_by_type function."""

from dataclasses import dataclass

import pytest

from solution import count_orders_by_type


@dataclass
class OrderStub:
    """A minimal stand-in for an order object with an order_type attribute."""

    order_type: str


def make_orders(order_types: list) -> list:
    """Build a list of OrderStub instances from a list of order type strings."""
    return [OrderStub(order_type=order_type) for order_type in order_types]


def test_empty_list_returns_empty_dict() -> None:
    result = count_orders_by_type([])
    assert result == {}


def test_single_order_returns_count_of_one() -> None:
    orders = make_orders(["online"])
    result = count_orders_by_type(orders)
    assert result == {"online": 1}


def test_multiple_orders_same_type_are_summed() -> None:
    orders = make_orders(["retail", "retail", "retail"])
    result = count_orders_by_type(orders)
    assert result == {"retail": 3}


def test_multiple_distinct_types_are_counted_separately() -> None:
    orders = make_orders(["online", "retail", "online", "wholesale"])
    result = count_orders_by_type(orders)
    assert result == {"online": 2, "retail": 1, "wholesale": 1}


def test_result_contains_only_seen_types() -> None:
    orders = make_orders(["online", "online"])
    result = count_orders_by_type(orders)
    assert "retail" not in result
    assert set(result.keys()) == {"online"}


def test_order_independent_of_input_order() -> None:
    orders_a = make_orders(["a", "b", "a", "c", "b", "a"])
    orders_b = make_orders(["c", "a", "b", "a", "a", "b"])
    result_a = count_orders_by_type(orders_a)
    result_b = count_orders_by_type(orders_b)
    assert result_a == result_b == {"a": 3, "b": 2, "c": 1}


def test_returns_new_dict_each_call() -> None:
    orders = make_orders(["online"])
    first_result = count_orders_by_type(orders)
    second_result = count_orders_by_type(orders)
    assert first_result == second_result
    assert first_result is not second_result


