import math

import pytest

from solution import calculate_distance_from_center


class TestCenterZeroBoundary:
    """center == 0 is an explicit special case short-circuiting the division."""

    @pytest.mark.parametrize("price", [0.0, 100.0, -100.0, 1e9])
    def test_returns_zero_regardless_of_price(self, price):
        assert calculate_distance_from_center(price, 0.0) == 0.0

    def test_return_type_is_float_for_zero_center(self):
        result = calculate_distance_from_center(50, 0)
        assert isinstance(result, float)


class TestPriceEqualsCenter:
    """price == center must yield exactly 0% distance, whatever the scale."""

    @pytest.mark.parametrize("value", [1.0, -1.0, 0.0001, 123456.789])
    def test_zero_distance(self, value):
        assert calculate_distance_from_center(value, value) == pytest.approx(0.0)


class TestDirectionalSign:
    """Sign of the result documents which side of center the price sits on."""

    def test_price_above_center_is_positive(self):
        assert calculate_distance_from_center(150.0, 100.0) == pytest.approx(50.0)

    def test_price_below_center_is_negative(self):
        assert calculate_distance_from_center(150.0, 200.0) == pytest.approx(-25.0)

    def test_negative_center_flips_intuitive_sign(self):
        # ((-50) - (-100)) / (-100) * 100 = (50 / -100) * 100 = -50.0
        # Documents the non-obvious behavior: price closer to zero than a
        # negative center still reports a *negative* percentage distance.
        assert calculate_distance_from_center(-50.0, -100.0) == pytest.approx(-50.0)

    def test_price_zero_with_positive_center(self):
        assert calculate_distance_from_center(0.0, 50.0) == pytest.approx(-100.0)


class TestRoundTripInvariant:
    """price can be reconstructed from the returned distance: a non-local
    contract stronger than re-deriving the formula for a single case."""

    @pytest.mark.parametrize(
        "price,center",
        [
            (150.0, 100.0),
            (75.0, 200.0),
            (-30.0, 60.0),
            (999.5, 333.25),
        ],
    )
    def test_reconstructs_original_price(self, price, center):
        distance = calculate_distance_from_center(price, center)
        reconstructed = center + (distance / 100.0) * center
        assert reconstructed == pytest.approx(price)
