"""Tests for _process_websocket_test_results."""

import pytest

from solution import _process_websocket_test_results


def test_error_present_returns_false_and_prints_error_message(capsys):
    result_container = {"error": "connection refused", "success": False}

    assert _process_websocket_test_results(result_container) is False

    out = capsys.readouterr().out
    assert "connection refused" in out
    assert "❌ WebSocket test failed" in out
    assert "Unknown error" not in out


def test_error_takes_precedence_over_truthy_success(capsys):
    """Pins branch ordering: an 'error' value wins even if 'success' is also truthy."""
    result_container = {"error": "timeout", "success": True}

    assert _process_websocket_test_results(result_container) is False

    out = capsys.readouterr().out
    assert "timeout" in out


def test_no_error_and_success_true_returns_true_without_printing(capsys):
    result_container = {"error": None, "success": True}

    assert _process_websocket_test_results(result_container) is True
    assert capsys.readouterr().out == ""


def test_no_error_and_success_false_returns_false_with_unknown_error(capsys):
    result_container = {"error": None, "success": False}

    assert _process_websocket_test_results(result_container) is False

    out = capsys.readouterr().out
    assert "❌ WebSocket test failed: Unknown error" in out


def test_empty_string_error_is_treated_as_no_error(capsys):
    """Boundary: '' is falsy, so it must fall through to the success branch,
    not be reported as a real error."""
    result_container = {"error": "", "success": True}

    assert _process_websocket_test_results(result_container) is True
    assert capsys.readouterr().out == ""


def test_missing_error_key_raises_keyerror():
    """Documents that the function requires 'error' to be present (no default)."""
    with pytest.raises(KeyError):
        _process_websocket_test_results({"success": True})


def test_missing_success_key_raises_keyerror_when_no_error():
    """Documents that 'success' is also required once 'error' is falsy."""
    with pytest.raises(KeyError):
        _process_websocket_test_results({"error": None})

